node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

const cartId = 'CART-cust_001';
const customerId = 'cust_001';
const productId = 'PROD-B98D14';
const cartItemId = 'CI-0035';  // next after CI-0034
const price = 79;

// Create the cart
db.prepare(\`
  INSERT INTO carts (cart_id, customer_id, subtotal, discount_amount, gift_wrap_fee, loyalty_discount, loyalty_points_redeemed, shipping_option, shipping_cost, total, applied_promo_codes_json, item_ids_json)
  VALUES (?, ?, ?, 0, 0, 0, 0, NULL, 0, ?, '[]', ?)
\`).run(cartId, customerId, price, price, JSON.stringify([cartItemId]));

// Add the cart item
db.prepare(\`
  INSERT INTO cart_items (cart_item_id, cart_id, customer_id, product_id, quantity, gift_wrap, variant_id)
  VALUES (?, ?, ?, ?, 1, 0, NULL)
\`).run(cartItemId, cartId, customerId, productId);

console.log('Cart and item created successfully.');

// Now read back the updated cart and items
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);
console.log('\nUpdated Cart:', JSON.stringify(cart, null, 2));

const items = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all(cartId);
console.log('\nCart Items:', JSON.stringify(items, null, 2));

// Also get product name for display
const product = db.prepare('SELECT product_id, name, price, category, brand FROM products WHERE product_id = ?').get(productId);
console.log('\nProduct Info:', JSON.stringify(product, null, 2));
"
